import java.util.Scanner;

public class Main {
    static long n, top, t, k, m = Long.MAX_VALUE, bs;

    static void recurse(long x, long s, long k, long kk) {
        if (s >= n) return;
        if (x == 0) {
            System.out.print(s);
            System.exit(0);
        }
        while (k > x) {
            k /= 10;
            kk--;
        }
        recurse(0, s + ((k * 10 + 1) - x) + kk + 1, k * 10 + 1, kk + 1);
        long t_val = x / k;
        recurse((k * 10 + 1) - x, s + kk + 1, k, kk);
        recurse(x - (k * t_val), s + (kk * t_val), k, kk);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = 1;
        bs = 1;
        while (k * 10 + 1 <= n) {
            k = k * 10 + 1;
            bs++;
        }
        for (int i = 0; i < n; i++) {
            recurse(n, 0, k, bs);
        }
        if (m == Long.MAX_VALUE) {
            m = Math.min(n, 11 - n + 2);
        }
        System.out.print(m);
        sc.close();
    }
}
